unsigned short __cdecl AAS_AreaTravelTime(int areanum, float *start, float *end)
{
  int intdist;
  float dist;
  float dir[3];

  dir[0] = start[0] - end[0];
  dir[1] = start[1] - end[1];
  dir[2] = start[2] - end[2];
  dist = VectorLength(dir);
  if ( AAS_AreaCrouch(areanum) )
    dist = dist * 1.3;
  else if ( AAS_AreaSwim(areanum) )
    dist = dist * 1;
  else
    dist = dist * 0.33;
  intdist = (int)dist;
  if ( intdist <= 0 )
    intdist = 1;
  return intdist;
}
