int __cdecl BotQueueConsoleMessage(bot_chatstate_t *cs, int type, char *Source)
{
  bot_consolemessage_t *msg;
  chatmsg_links_t      *links;

  msg = AllocConsoleMessage();
  if ( !msg )
    return bi_Print(3, aEmptyConsoleMe);
  msg->time = AAS_Time();
  msg->type = type;
  strncpy(msg->message, Source, 0x96u);
  links = &BotChatMsgLinksCS(cs);
  msg->next = NULL;
  if ( links->last )
  {
    links->last->next = msg;
    msg->prev = links->last;
    links->last = msg;
    ++links->count;
    return (intptr_t)cs;
  }
  else
  {
    links->last  = msg;
    links->first = msg;
    msg->prev    = NULL;
    ++links->count;
    return (intptr_t)cs;
  }
}
