float __cdecl LibVarStringValue(char *string)
{
  int dotfound;
  float value;

  dotfound = 0;
  value = 0.0f;
  while ( *string )
  {
    if ( *string < '0' || *string > '9' )
    {
      if ( dotfound || *string != '.' )
        return 0.0f;
      dotfound = 10;
      ++string;
    }
    if ( dotfound )
    {
      value = value + (float)(*string - '0') / (float)dotfound;
      dotfound *= 10;
    }
    else
    {
      value = value * 10.0 + (float)(*string - '0');
    }
    ++string;
  }
  return value;
}

